#pragma once
#include <Arduino.h>
#include "src/ricmoo/qrcode_encoder.h"

namespace nasqr {
constexpr uint8_t VERSION=5, SCALE=4, QUIET=4;
constexpr int SIDE=(17+4*VERSION+2*QUIET)*SCALE;
static_assert(SIDE==180&&SIDE<=240,"QR must fit the physical display");
MSRQRCode wifi,web;
uint8_t wifiModules[256],webModules[256];
bool wifiReady=false,webReady=false;
String wifiPayload(const String& ssid,const String& password) {
  // Both fields are generated by this firmware: ASCII letters/digits/hyphen.
  return "WIFI:T:WPA;S:"+ssid+";P:"+password+";;";
}
String webPayload(const String& token) {return "http://192.168.4.1/?pair=1#pair="+token;}
bool encode(MSRQRCode& qr,uint8_t* buffer,const String& payload) {
  return msr_qrcode_getBufferSize(VERSION)<=256 && msr_qrcode_initText(&qr,buffer,VERSION,MSR_QR_ECC_MEDIUM,payload.c_str())==0;
}
void initializeWifi(const String& ssid,const String& password) {wifiReady=encode(wifi,wifiModules,wifiPayload(ssid,password));}
void initializeWeb(const String& token) {webReady=encode(web,webModules,webPayload(token));}
void printDemo(const char* label,const String& payload) {
  MSRQRCode demo;uint8_t modules[256];
  if(!encode(demo,modules,payload)){Serial.println("QR_TEST_FAILED");return;}
  Serial.print("QR_TEST_");Serial.print(label);Serial.println("_BEGIN");
  for(uint8_t y=0;y<demo.size;y++){for(uint8_t x=0;x<demo.size;x++)Serial.print(msr_qrcode_getModule(&demo,x,y)?'1':'0');Serial.println();}
  Serial.print("QR_TEST_");Serial.print(label);Serial.println("_END");
}
void serialDemo() {
  // Public fixtures only. Never expose the current WiFi key or pair token.
  printDemo("WIFI",wifiPayload("MSR-NAS-DEMO","EXAMPLEONLY123456"));
  printDemo("WEB",webPayload("00000000000000000000000000000000"));
}
}
